mapper.select:
SELECT campaign_id AS campaignId, name, objective, status, created_at AS createdAt, updated_at AS updatedAt, campaign_type AS campaignType
FROM mk_campaign
WHERE tenant_id = #{tenantId}
AND campaign_type=#{campaignType}

    AND organization_id IN

        #{organization}




        AND (shop_id IS NULL OR shop_id = '')

            AND (shop_id IS NULL OR shop_id = '' OR shop_id IN

                #{shop}
            )



ORDER BY created_at DESC

SELECT  FROM mk_definition_version
WHERE tenant_id = #{tenantId} AND definition_id = #{definitionId} AND semantic_hash = #{semanticHash}
LIMIT 1

SELECT  FROM mk_approval_case
WHERE tenant_id = #{tenantId} AND case_id = #{caseId}
FOR UPDATE

SELECT  FROM mk_approval_case
WHERE tenant_id = #{tenantId}
ORDER BY updated_at DESC
LIMIT #{limit}

mapper.update:
UPDATE mk_audit_head
SET last_chain_index = #{chainIndex}, last_entry_hash = #{entryHash}, updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND last_chain_index = #{expectedChainIndex}
  AND last_entry_hash = #{expectedEntryHash}

UPDATE mk_release_slot SET latest_generation = #{latestGeneration}, updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND environment_name = #{environmentName} AND cell_id = #{cellId}
  AND runtime_name = #{runtimeName} AND namespace_name = #{namespaceName}

UPDATE mk_runtime_ack
SET status_name = #{statusName}, build_digest = #{buildDigest}, supported_abis = #{supportedAbis},
    warmed_artifact_ids = #{warmedArtifactIds}, capacity_value = #{capacityValue},
    acknowledged_at = #{acknowledgedAt}, signature_key_id = #{signatureKeyId},
    signature_value = #{signatureValue}
WHERE tenant_id = #{tenantId} AND manifest_id = #{manifestId} AND runtime_id = #{runtimeId}

UPDATE mk_release_slot
SET stable_generation = #{stableGeneration}, desired_generation = #{desiredGeneration},
    activation_sequence = #{activationSequence}, updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND environment_name = #{environmentName} AND cell_id = #{cellId}
  AND runtime_name = #{runtimeName} AND namespace_name = #{namespaceName}
  AND desired_generation = #{expectedDesiredGeneration}
  AND activation_sequence = #{expectedActivationSequence}

mapper.select:
SELECT switch_sequence FROM mk_kill_switch
WHERE tenant_id = #{tenantId} AND namespace_name = #{namespace}
FOR UPDATE

mapper.update:
UPDATE mk_kill_switch
SET switch_sequence = #{switchSequence}, enabled_value = #{enabledValue}, reason_text = #{reasonText},
    updated_by = #{updatedBy}, updated_at = #{updatedAt}, directive_json = #{directiveJson}
WHERE tenant_id = #{tenantId} AND namespace_name = #{namespaceName}

mapper.select:
SELECT manifest_json AS manifestJson, state_name AS stateName
FROM mk_release_manifest WHERE tenant_id = #{tenantId}
ORDER BY created_at DESC LIMIT #{limit}

SELECT COUNT(*) AS readyCount, COALESCE(SUM(capacity_value), 0) AS totalCapacity
FROM mk_runtime_ack
WHERE tenant_id = #{tenantId} AND manifest_id = #{manifestId}
  AND status_name = #{statusName} AND acknowledged_at >= #{leaseFloor}

SELECT COUNT(*) FROM mk_approval_case
WHERE tenant_id = #{tenantId} AND case_id = #{caseId} AND definition_id = #{definitionId}
  AND definition_version = #{version} AND status = 'APPROVED'

SELECT semantic_hash FROM mk_definition_version
WHERE tenant_id = #{tenantId} AND definition_id = #{definitionId} AND version_no = #{version}
  AND status = 'APPROVED'

SELECT graph_json FROM mk_definition_version
WHERE tenant_id = #{tenantId} AND definition_id = #{definitionId} AND version_no = #{version}
  AND status = 'APPROVED'

SELECT stable_generation AS stableGeneration, desired_generation AS desiredGeneration,
       latest_generation AS latestGeneration, activation_sequence AS activationSequence
FROM mk_release_slot
WHERE tenant_id = #{tenantId} AND environment_name = #{environment} AND cell_id = #{cell}
  AND runtime_name = #{runtime} AND namespace_name = #{namespace}
FOR UPDATE

SELECT generation_no FROM mk_release_manifest
WHERE tenant_id = #{tenantId} AND environment_name = #{environment} AND cell_id = #{cell}
  AND runtime_name = #{runtime} AND namespace_name = #{namespace} AND state_name = 'ACTIVE'
ORDER BY generation_no DESC LIMIT #{limit}

SELECT manifest_json AS manifestJson, state_name AS stateName
FROM mk_release_manifest WHERE tenant_id = #{tenantId} AND manifest_id = #{manifestId}
FOR UPDATE

SELECT manifest_json AS manifestJson, state_name AS stateName
FROM mk_release_manifest
WHERE tenant_id = #{tenantId} AND environment_name = #{environment} AND cell_id = #{cell}
  AND runtime_name = #{runtime} AND namespace_name = #{namespace} AND generation_no = #{generation}

SELECT directive_json FROM mk_activation_directive
WHERE tenant_id = #{tenantId} AND environment_name = #{environment} AND cell_id = #{cell}
  AND runtime_name = #{runtime} AND namespace_name = #{namespace} AND generation_no = #{generation}
ORDER BY activation_sequence DESC LIMIT 1

SELECT payload_hash AS payloadHash, state_name AS stateName, response_json AS responseJson,
       expires_at AS expiresAt
FROM mk_control_command
WHERE tenant_id = #{tenantId} AND operation_name = #{operationName}
  AND idempotency_key = #{idempotencyKey}
FOR UPDATE

mapper.delete:
DELETE FROM mk_control_command
WHERE tenant_id = #{tenantId} AND operation_name = #{operationName}
  AND idempotency_key = #{idempotencyKey}

mapper.update:
UPDATE mk_control_command SET state_name = 'COMPLETED', response_json = #{responseJson}
WHERE tenant_id = #{tenantId} AND operation_name = #{operationName}
  AND idempotency_key = #{idempotencyKey}

UPDATE mk_outbox
SET publish_attempts = #{attempts}, next_attempt_at = #{nextAttemptAt}, last_error = #{error}
WHERE tenant_id = #{tenantId} AND event_id = #{eventId} AND published_at IS NULL
